    assert is_adult(17) is False


def test_age_zero_is_not_adult():
    assert is_adult(0) is False


def test_ages_below_18_are_not_adult():
    for age in (1, 5, 10, 15, 16):
        assert is_adult(age) is False


def test_negative_age_raises_value_error():
    with pytest.raises(ValueError):
        is_adult(-1)


def test_large_negative_age_raises_value_error():
    with pytest.raises(ValueError):
        is_adult(-100)

def is_adult(age):
    if age < 0:
        raise ValueError("negative age")
    return age >= 18

