import pytest

from app import take_first


def test_zero_returns_empty_list():
    assert take_first([1, 2], 0) == []


def test_one_returns_first_element():
    assert take_first([1, 2, 3], 1) == [1]


def test_partial_count_preserves_order():
    assert take_first([10, 20, 30, 40], 2) == [10, 20]


def test_count_equal_to_length_returns_all():
    assert take_first([1, 2, 3], 3) == [1, 2, 3]


def test_count_greater_than_length_returns_all():
    assert take_first([1, 2, 3], 10) == [1, 2, 3]


def test_empty_list_returns_empty():
    assert take_first([], 5) == []


def test_empty_list_with_zero_returns_empty():
    assert take_first([], 0) == []


def test_does_not_mutate_input():
    items = [1, 2, 3]
    take_first(items, 2)
    assert items == [1, 2, 3]


def test_negative_raises_value_error():
    with pytest.raises(ValueError):
        take_first([1, 2, 3], -1)

def take_first(items, n):
    if n < 0:
        raise ValueError("negative count")
    return [items[i] for i in range(min(n, len(items)))]

